const float sigma = 50.0f;
const uint SAMPLES = 5U;
const float w = 1.0f / float(SAMPLES);
const float SQRT_TWO = 1.41421356237f;
const float PI = 3.14159265359f;
const float TWO_PI = 6.28318530718f;

/**
 * pcg1d, from:
 * Mark Jarzynski and Marc Olano, Hash Functions for GPU Rendering, 
 * Journal of Computer Graphics Techniques (JCGT), vol. 9, no. 3, 21-38, 2020
 * Available online http://jcgt.org/published/0009/03/02/
 * Code at: https://www.shadertoy.com/view/XlGcRh
 */
uint pcg(uint v) {
	uint state = v * 747796405u + 2891336453u;
	uint word = ((state >> ((state >> 28u) + 4u)) ^ state) * 277803737u;
	return (word >> 22u) ^ word;
}

/**
 * pcg3d, from:
 * Mark Jarzynski and Marc Olano, Hash Functions for GPU Rendering, 
 * Journal of Computer Graphics Techniques (JCGT), vol. 9, no. 3, 21-38, 2020
 * Available online http://jcgt.org/published/0009/03/02/
 * Code at: https://www.shadertoy.com/view/XlGcRh
 */
uvec3 hash3u(uvec3 v) {
    v = v * 1664525u + 1013904223u;
    v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y;
    v ^= v >> 16u;
    v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y;
    return v;
}

// Maps a random u32 to a random float in [0,1), see https://blog.bithole.dev/blogposts/random-float/
float mapf(uint x) {
    return uintBitsToFloat((x >> 9u) | 0x3F800000u) - 1.0f;
}

// Maps a random u32 to a random float in [0,1), see https://blog.bithole.dev/blogposts/random-float/
vec2 map2f(uvec2 x) {
    return uintBitsToFloat((x >> uvec2(9u)) | uvec2(0x3F800000u)) - 1.0f;
}

// Normal distribution sampling from https://gpuopen.com/learn/sampling-normal-gaussian-distribution-gpus/
vec2 sampleGaussBoxMuller(vec2 r, float sigma) {
    float a = sigma * sqrt(-2.0f * log(1.0f - r.x));
    float b = TWO_PI * r.y;
    return vec2(cos(b), sin(b)) * a;
}

float erfinv(float x) {
    float tt1, tt2, lnx, sgn;
    sgn = (x < 0.0f) ? -1.0f : 1.0f;
    x = (1.0f - x) * (1.0f + x);
    lnx = log(x);
    tt1 = 2.0f / (3.14159265359f * 0.147f) + 0.5f * lnx;
    tt2 = 1.0f / (0.147f) * lnx;
    return (sgn * sqrt(-tt1 + sqrt(tt1 * tt1 - tt2)));
}

float sampleNormalDistributionInvCDF(float r, float mean, float sigma) {
    return mean + SQRT_TWO * sigma * erfinv(2.0f * r - 1.0f);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec4 color = vec4(0.0f);
    for (uint i = 0U; i < SAMPLES; i++) {
